/**
 * mpl_render: a codemode tool that draws matplotlib-style charts with mpl (github.com/ivarvong/mpl)
 * from a JSON call list, writes PNG/SVG files, and returns the PNG so a script can show it with image().
 */
import type { ExtensionAPI, ToolDefinition, ToolNamespace } from "@earendil-works/pi-coding-agent";
import { Type, type TSchema } from "typebox";
import { MPL_DEFAULT_THEME, renderChart, type MplRenderInput } from "./render.ts";
import { MPL_FIGURE_METHODS } from "./replay.ts";

const MPL_RENDER_TOOL_NAME = "mpl_render";

export const mplInstructions = `Reference for mpl_render. mpl is a pixel-exact TypeScript port of matplotlib 3.11: calls follow matplotlib's object API (ax.<method>(*args, **kwargs)), kwargs and rc keys included.

Spec: { calls, theme?, rc?, grid?, format?, scale?, name?, tight_layout? }
- calls: [method, [positional args], {kwargs}], applied in order to the current Axes. ax.plot(x, y, 'o-', label='a') is ["plot", [x, y, "o-"], { label: "a" }].
- grid: { rows, cols, sharex?, sharey?, width_ratios?, height_ratios? }. Axes are numbered row-major from 0; ["sca", [i]] makes Axes i current; ["twinx", []] adds a twin and makes it current.
- Figure calls take a "fig." prefix: ${[...MPL_FIGURE_METHODS].map((m) => `fig.${m}`).join(", ")}. fig.colorbar maps the last imshow or colour-mapped scatter on the current Axes.
- Values: {"$float": "nan"} is NaN. Kwarg {"$transform": "axes"} is ax.transAxes.
- theme: "${MPL_DEFAULT_THEME}" (default, dark), "pro-slate" (light), "pro-dark", or any matplotlib style name. rc overrides keys, e.g. { "figure.figsize": [9, 4] }.
- scale: PNG pixel multiplier from 0.25 to 4, default 2 (1440x840 at the default size); 3 for print.
- format: "png" (default), "svg", or "both". Files land in ~/.pi/agent/work/charts/<date>/; tight_layout runs unless the calls lay out the figure.

Dates:
- {"$dates": ["2026-01-01", ...]} is Date[], {"$date": "..."} one Date; naive ISO strings are UTC. plot, bar, text, axvline and fill_between take them.
- Ticks: ["$concise_x", []] for ConciseDateFormatter, or ["$date_x", ["MonthLocator", { interval: 1 }, "%b %d" | "concise"]].
- annotate takes epoch days (ms / 86400000) as coordinates.

Colours (Macchiato): red #ed8796, peach #f5a97f, yellow #eed49f, green #a6da95, teal #8bd5ca, blue #8aadf4, mauve #c6a0f6, pink #f5bde6, muted text #a5adcb. Cycle C0..C7 = blue, mauve, green, peach, red, teal, yellow, pink.

Chart types: line, step, scatter, bar/barh (bottom/left for stacks), hist, boxplot, errorbar, fill_between, imshow + fig.colorbar, axhline/axvline/axhspan/axvspan, text, annotate. For shares use barh; for distributions use hist or boxplot; for legend placement use loc and ncols.

Gotchas:
- Unknown kwargs and rc keys throw, as in matplotlib; the error names the call index and the offending key.
- Scatter legend: label a proxy ["plot", [[], [], "o"], { color: "C0", label: "name" }] rather than the scatter.
- Text: Latin, Greek, arrows and math symbols; use ASCII for tree labels and ~ for approximations.
- Keep each series under ~100k points.

Done when: the image you showed has no overlapping or clipped labels, no legend covering data, and readable ticks; otherwise adjust (figsize, ticks, legend loc, ylim headroom) and re-render.`;

export const mplToolNamespace: ToolNamespace = { name: "mpl", instructions: mplInstructions };

export const mplRenderParameters = Type.Object({
	calls: Type.Array(Type.Array(Type.Unknown(), { minItems: 1, maxItems: 3 }), {
		description: '[method, [positional args], {kwargs}], e.g. ["bar", [names, values], { color: "C1" }]',
	}),
	theme: Type.Optional(Type.String({ description: `default ${MPL_DEFAULT_THEME}` })),
	rc: Type.Optional(Type.Record(Type.String(), Type.Unknown())),
	grid: Type.Optional(
		Type.Object({
			rows: Type.Integer(),
			cols: Type.Integer(),
			sharex: Type.Optional(Type.Union([Type.Boolean(), Type.String()])),
			sharey: Type.Optional(Type.Union([Type.Boolean(), Type.String()])),
			width_ratios: Type.Optional(Type.Array(Type.Number())),
			height_ratios: Type.Optional(Type.Array(Type.Number())),
		}),
	),
	format: Type.Optional(Type.Union([Type.Literal("png"), Type.Literal("svg"), Type.Literal("both")])),
	scale: Type.Optional(Type.Number()),
	name: Type.Optional(Type.String()),
	tight_layout: Type.Optional(Type.Boolean()),
});

export const mplRenderOutput = Type.Object({
	image: Type.Optional(Type.Object({ type: Type.Literal("image"), data: Type.String(), mimeType: Type.String() })),
	pngPath: Type.Optional(Type.String()),
	svgPath: Type.Optional(Type.String()),
	error: Type.Optional(Type.String()),
});

export function toMplRenderToolDefinition(outDir?: () => string): ToolDefinition<TSchema, undefined> {
	return {
		name: MPL_RENDER_TOOL_NAME,
		label: "mpl render",
		description:
			'Chart data as PNG/SVG through the matplotlib API. Read describeNamespace("mpl") before the first chart; show the result with image(r.image).',
		parameters: mplRenderParameters as unknown as TSchema,
		outputSchema: mplRenderOutput as unknown as TSchema,
		exposure: "codemode",
		namespace: mplToolNamespace,
		annotations: { readOnlyHint: false, destructiveHint: false, idempotentHint: false, openWorldHint: false },
		async execute(_toolCallId, params) {
			const input = params as MplRenderInput;
			try {
				const out = renderChart(input, outDir?.());
				const image = out.png
					? { type: "image" as const, data: Buffer.from(out.png).toString("base64"), mimeType: "image/png" as const }
					: undefined;
				const structured = {
					...(image && { image }),
					...(out.pngPath && { pngPath: out.pngPath }),
					...(out.svgPath && { svgPath: out.svgPath }),
				};
				const paths = [out.pngPath, out.svgPath].filter(Boolean).join("\n");
				return {
					content: [...(image ? [image] : []), { type: "text" as const, text: paths }],
					structuredContent: structured as never,
					details: undefined,
				};
			} catch (error) {
				const message = error instanceof Error ? error.message : String(error);
				return {
					content: [{ type: "text" as const, text: `mpl_render failed: ${message}` }],
					structuredContent: { error: message } as never,
					details: undefined,
					isError: true,
				};
			}
		},
	};
}

export default function mplExtension(pi: ExtensionAPI): void {
	pi.registerTool(toMplRenderToolDefinition());
}

/** Renders an mpl chart spec to PNG/SVG files. No pi imports, so tests drive it directly. */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { availableStyles, registerColormapRgba, registerColormaps, registerFonts } from "mpl";
import { allColormaps } from "mpl/colormaps/all";
import { allColormapRgba } from "mpl/colormaps/all.rgba";
import { allFonts } from "mpl/fonts/all";
import { buildFigure, type MplCall, type MplGrid } from "./replay.ts";

registerFonts(...allFonts);
registerColormaps(...allColormaps);
registerColormapRgba(...allColormapRgba);

/** Themes this extension ships as .mplstyle files under styles/. */
const LOCAL_THEMES = ["catppuccin-macchiato"] as const;
export const MPL_DEFAULT_THEME = "catppuccin-macchiato";
/** Hi-dpi by default: 2x pixels, 1440x840 at the themes' 7.2x4.2 in figure size. */
export const MPL_DEFAULT_SCALE = 2;
/** Every accepted theme name: local ones first, then mpl's bundled styles (pro-slate, pro-dark, ggplot, ...). */
export const MPL_THEMES: readonly string[] = [...LOCAL_THEMES, ...availableStyles().filter((s) => s !== "default"), "default"];

const styleText = new Map<string, string>();
function themeStyle(theme: string): unknown {
	if ((LOCAL_THEMES as readonly string[]).includes(theme)) {
		let text = styleText.get(theme);
		if (text === undefined) {
			text = readFileSync(new URL(`./styles/${theme}.mplstyle`, import.meta.url), "utf8");
			styleText.set(theme, text);
		}
		return text;
	}
	if (theme === "default") return [];
	if (!MPL_THEMES.includes(theme)) throw new Error(`unknown theme "${theme}"; use one of ${MPL_THEMES.join(", ")}`);
	return theme;
}

export interface MplRenderInput {
	readonly theme?: string;
	readonly rc?: Readonly<Record<string, unknown>>;
	readonly grid?: MplGrid;
	readonly calls: readonly MplCall[];
	readonly format?: "png" | "svg" | "both";
	/** PNG pixel multiplier (hi-dpi). Default MPL_DEFAULT_SCALE. */
	readonly scale?: number;
	/** File stem, such as "latency-by-region". */
	readonly name?: string;
	/** Run fig.tight_layout() after the calls. Default true unless the calls already lay out the figure. */
	readonly tight_layout?: boolean;
}

export interface MplRenderOutput {
	readonly png?: Uint8Array;
	readonly pngPath?: string;
	readonly svgPath?: string;
	readonly width?: number;
	readonly height?: number;
	readonly theme: string;
}

/** Default output directory: ~/.pi/agent/work/charts/<YYYY-MM-DD>. */
export function defaultChartDir(now = new Date()): string {
	return join(homedir(), ".pi", "agent", "work", "charts", now.toISOString().slice(0, 10));
}

function fileStem(name: string | undefined, now: Date): string {
	const slug = (name ?? "chart").toLowerCase().replace(/[^a-z0-9._-]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60) || "chart";
	return `${slug}-${now.toISOString().slice(11, 19).replaceAll(":", "")}`;
}

/** PNG width and height from the IHDR chunk. */
function pngSize(png: Uint8Array): { width: number; height: number } {
	const view = new DataView(png.buffer, png.byteOffset, png.byteLength);
	return { width: view.getUint32(16), height: view.getUint32(20) };
}

export function renderChart(input: MplRenderInput, outDir = defaultChartDir()): MplRenderOutput {
	const theme = input.theme ?? MPL_DEFAULT_THEME;
	const scale = input.scale ?? MPL_DEFAULT_SCALE;
	if (!(scale >= 0.25 && scale <= 4)) throw new Error(`scale must be between 0.25 and 4, got ${scale}`);
	const fig = buildFigure({ style: themeStyle(theme), rc: input.rc, grid: input.grid, calls: input.calls });
	const laidOut = input.calls.some((c) => c[0] === "fig.tight_layout" || c[0] === "fig.subplots_adjust");
	if (input.tight_layout ?? !laidOut) fig.tight_layout();

	const format = input.format ?? "png";
	const now = new Date();
	const stem = fileStem(input.name, now);
	mkdirSync(outDir, { recursive: true });

	let png: Uint8Array | undefined;
	let pngPath: string | undefined;
	let svgPath: string | undefined;
	if (format !== "svg") {
		png = fig.toPNGSync({ scale });
		pngPath = join(outDir, `${stem}.png`);
		writeFileSync(pngPath, png);
	}
	if (format !== "png") {
		svgPath = join(outDir, `${stem}.svg`);
		writeFileSync(svgPath, fig.toSVG());
	}
	return { png, pngPath, svgPath, theme, ...(png ? pngSize(png) : {}) };
}

/**
 * Replays an mpl chart spec (a JSON list of [method, args, kwargs] calls) onto a Figure.
 * Adapted from mpl's tools/replay-core.ts (buildWith), which mpl does not export. The spec is data:
 * every method name is checked against an allow-list, so a codemode script cannot reach anything
 * but Axes and Figure drawing methods.
 */
import {
	AutoDateLocator,
	Axes,
	ConciseDateFormatter,
	DateFormatter,
	DayLocator,
	Figure,
	HourLocator,
	MinuteLocator,
	MonthLocator,
	SecondLocator,
	YearLocator,
	subplots,
} from "mpl";

/** One drawing call: [method, positional args, keyword args]. */
export type MplCall = readonly [method: string, args?: readonly unknown[], kwargs?: Readonly<Record<string, unknown>>];

export interface MplGrid {
	readonly rows: number;
	readonly cols: number;
	readonly sharex?: boolean | string;
	readonly sharey?: boolean | string;
	readonly width_ratios?: readonly number[];
	readonly height_ratios?: readonly number[];
}

export interface MplFigureSpec {
	/** Passed to subplots({ style }): a bundled name, .mplstyle text, an rc object, or a list of those. */
	readonly style: unknown;
	readonly rc?: Readonly<Record<string, unknown>>;
	readonly grid?: MplGrid;
	readonly calls: readonly MplCall[];
}

/** Thrown for a spec mistake (unknown method, bad index); the message is meant for the model. */
export class MplSpecError extends Error {
	override readonly name = "MplSpecError";
}

type Dyn = Record<string, (...args: unknown[]) => unknown>;

const NOT_DRAWING = new Set(["constructor", "spec", "addAxesAt", "addAxesFromSpec", "add_subplot", "subplots", "toScene"]);

function drawingMethods(proto: object): ReadonlySet<string> {
	const names = new Set<string>();
	for (let p: object | null = proto; p && p !== Object.prototype; p = Object.getPrototypeOf(p)) {
		for (const name of Object.getOwnPropertyNames(p)) {
			if (name.startsWith("_") || NOT_DRAWING.has(name) || /^to[A-Z]|^svg|^png/.test(name)) continue;
			const d = Object.getOwnPropertyDescriptor(p, name);
			if (d && typeof d.value === "function") names.add(name);
		}
	}
	return names;
}

/** Axes methods a spec may call, such as plot, bar, set_title. */
export const MPL_AXES_METHODS: ReadonlySet<string> = drawingMethods(Axes.prototype);
/** Figure methods a spec may call as "fig.<name>", such as fig.suptitle. */
export const MPL_FIGURE_METHODS: ReadonlySet<string> = new Set(
	["text", "suptitle", "supxlabel", "supylabel", "subplots_adjust", "autofmt_xdate", "tight_layout", "colorbar"].filter(
		(name) => typeof (Figure.prototype as unknown as Dyn)[name] === "function",
	),
);
/** Pseudo-calls the replayer handles itself. */
export const MPL_SPECIAL_CALLS = ["sca", "twinx", "$concise_x", "$date_x"] as const;

const DATE_LOCATORS: Readonly<Record<string, new (kw?: unknown) => unknown>> = {
	AutoDateLocator: AutoDateLocator as never,
	YearLocator: YearLocator as never,
	MonthLocator: MonthLocator as never,
	DayLocator: DayLocator as never,
	HourLocator: HourLocator as never,
	MinuteLocator: MinuteLocator as never,
	SecondLocator: SecondLocator as never,
};

/** A naive ISO date-time as UTC (a date alone becomes midnight); a string with an offset or Z is kept. */
function toDate(s: unknown): Date {
	if (typeof s === "number") return new Date(s);
	if (typeof s !== "string") throw new MplSpecError(`$date/$dates expects ISO strings or epoch ms, got ${JSON.stringify(s)}`);
	const hasZone = /([zZ]|[+-]\d\d:?\d\d)$/.test(s);
	const iso = s.includes("T") || s.includes(" ") ? s.replace(" ", "T") : `${s}T00:00`;
	const d = new Date(hasZone ? iso : `${iso}Z`);
	if (Number.isNaN(d.getTime())) throw new MplSpecError(`invalid date ${JSON.stringify(s)}`);
	return d;
}

/** JSON values to mpl values at any depth: {$date}, {$dates}, {$float: "nan"|"inf"|"-inf"}. */
export function decodeValue(a: unknown): unknown {
	if (Array.isArray(a)) return a.map(decodeValue);
	if (a === null || typeof a !== "object") return a;
	const o = a as Record<string, unknown>;
	if ("$dates" in o) {
		if (!Array.isArray(o.$dates)) throw new MplSpecError("$dates expects an array");
		return o.$dates.map(toDate);
	}
	if ("$date" in o) return toDate(o.$date);
	if ("$float" in o) {
		const s = String(o.$float);
		return s === "nan" ? NaN : s === "inf" ? Infinity : s === "-inf" ? -Infinity : Number(s);
	}
	return a;
}

function decodeKwargs(kwargs: Readonly<Record<string, unknown>> | undefined, ax: Axes): Record<string, unknown> {
	const out: Record<string, unknown> = {};
	for (const [k, v] of Object.entries(kwargs ?? {})) {
		if (v && typeof v === "object" && "$transform" in v) {
			const t = (v as { $transform: unknown }).$transform;
			if (t !== "axes" && t !== "data") throw new MplSpecError(`$transform must be "axes" or "data"`);
			out[k] = t === "axes" ? ax.transAxes : ax.transData;
		} else out[k] = decodeValue(v);
	}
	return out;
}

function withKwargs(args: readonly unknown[], kw: Record<string, unknown>): unknown[] {
	return Object.keys(kw).length > 0 ? [...args, kw] : [...args];
}

function unknownMethod(fn: string): MplSpecError {
	return new MplSpecError(
		`unknown call "${fn}". Axes methods: ${[...MPL_AXES_METHODS].sort().join(", ")}. ` +
			`Figure methods (prefix "fig."): ${[...MPL_FIGURE_METHODS].join(", ")}. Special: ${MPL_SPECIAL_CALLS.join(", ")}.`,
	);
}

/** Builds the Figure for a spec. Throws MplSpecError for spec mistakes and mpl's own errors for bad kwargs. */
export function buildFigure(spec: MplFigureSpec): Figure {
	const base = { style: spec.style, rc: spec.rc ?? {} };
	let fig: Figure;
	let axes: Axes[];
	if (spec.grid) {
		const { rows, cols, width_ratios, height_ratios, ...gridKw } = spec.grid;
		const ratios = { ...(width_ratios && { width_ratios }), ...(height_ratios && { height_ratios }) };
		const gridspec_kw = Object.keys(ratios).length > 0 ? { gridspec_kw: ratios } : {};
		const [f, made] = subplots(rows, cols, { ...gridKw, ...gridspec_kw, ...base, squeeze: false } as never);
		fig = f;
		axes = (made as unknown as Axes[][]).flat();
	} else {
		const [f, ax] = subplots(base as never);
		fig = f;
		axes = [ax];
	}
	let ax = axes[0] as Axes;

	spec.calls.forEach((call, index) => {
		if (!Array.isArray(call) || typeof call[0] !== "string") {
			throw new MplSpecError(`calls[${index}] must be [method, args?, kwargs?], got ${JSON.stringify(call)}`);
		}
		const [fn, args0 = [], kwargs] = call;
		if (!Array.isArray(args0) || Array.isArray(kwargs) || call.length > 3) {
			throw new MplSpecError(
				`calls[${index}] ${fn}: expected [method, [positional args], {kwargs}]; wrap all positional args in one array, ` +
					`e.g. ["bar", [["a", "b"], [3, 7]], { color: "C1" }]`,
			);
		}
		const args = args0.map(decodeValue);
		try {
			if (fn === "sca") {
				const i = args[0];
				if (typeof i !== "number" || !axes[i]) throw new MplSpecError(`sca: no Axes ${String(i)} (have ${axes.length})`);
				ax = axes[i] as Axes;
				return;
			}
			if (fn === "twinx") {
				ax = ax.twinx();
				axes.push(ax);
				return;
			}
			if (fn === "$concise_x") {
				const loc = new AutoDateLocator();
				ax.xaxis.set_major_locator(loc as never);
				ax.xaxis.set_major_formatter(new ConciseDateFormatter(loc as never, (kwargs ?? {}) as never) as never);
				return;
			}
			if (fn === "$date_x") {
				// ["$date_x", [locator, locatorKwargs?, formatter?]]: formatter is a strftime string or "concise"
				const [name, lkw, fmt] = args0 as [string, Record<string, unknown> | undefined, string | undefined];
				const Loc = DATE_LOCATORS[name];
				if (!Loc) throw new MplSpecError(`$date_x: unknown locator ${name}; use one of ${Object.keys(DATE_LOCATORS).join(", ")}`);
				const loc = new Loc(lkw ?? {});
				ax.xaxis.set_major_locator(loc as never);
				if (fmt === "concise") ax.xaxis.set_major_formatter(new ConciseDateFormatter(loc as never, {}) as never);
				else if (typeof fmt === "string") ax.xaxis.set_major_formatter(new DateFormatter(fmt) as never);
				return;
			}
			if (fn.startsWith("fig.")) {
				const name = fn.slice(4);
				if (!MPL_FIGURE_METHODS.has(name)) throw unknownMethod(fn);
				const kw = decodeKwargs(kwargs, ax);
				if (name === "colorbar") {
					const mappable = [...ax.artists]
						.reverse()
						.find((a) => a.kind === "image" || (a.kind === "scatter" && a.mappable.kind === "some"));
					if (!mappable) throw new MplSpecError("fig.colorbar: no imshow or colour-mapped scatter on the current Axes");
					(fig as unknown as Dyn).colorbar?.(mappable, ...(Object.keys(kw).length ? [kw] : []));
					return;
				}
				(fig as unknown as Dyn)[name]?.(...withKwargs(args, kw));
				return;
			}
			if (!MPL_AXES_METHODS.has(fn)) throw unknownMethod(fn);
			(ax as unknown as Dyn)[fn]?.(...withKwargs(args, decodeKwargs(kwargs, ax)));
		} catch (error) {
			if (error instanceof MplSpecError && error.message.startsWith(`calls[`)) throw error;
			const message = error instanceof Error ? error.message : String(error);
			throw new MplSpecError(`calls[${index}] ${fn}: ${message}`);
		}
	});
	return fig;
}

